  ) AS v(kind, tbl, old_name, new_name)
  LOOP
    IF r.kind = 'C' THEN
      IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = r.old_name AND conrelid = ('public.' || r.tbl)::regclass) THEN
        EXECUTE format('ALTER TABLE public.%I RENAME CONSTRAINT %I TO %I', r.tbl, r.old_name, r.new_name);
      END IF;
    ELSE
      IF to_regclass('public.' || quote_ident(r.old_name)) IS NOT NULL THEN
        EXECUTE format('ALTER INDEX public.%I RENAME TO %I', r.old_name, r.new_name);
      END IF;
    END IF;
  END LOOP;
